{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h2",
        "intro_text",
        "attractions_h3",
        "disneyland_card",
        "ghibli_card",
        "teamlab_card",
        "ueno_zoo_card",
        "skytree_card"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Tokyo Family Adventures: Kid-Friendly Attractions",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Planning a trip to Tokyo with children aged 8-12 offers a fantastic array of engaging experiences. Many popular attractions cater to this age group with interactive exhibits and entertainment, often providing convenient online ticket booking to streamline your visit."
      },
      "children": []
    },
    "attractions_h3": {
      "type": "Text",
      "props": {
        "text": "Top Attractions with Online Booking & Estimated Durations",
        "variant": "h3"
      },
      "children": []
    },
    "disneyland_card": {
      "type": "Card",
      "props": {},
      "children": [
        "disneyland_content_stack"
      ]
    },
    "disneyland_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "disneyland_title",
        "disneyland_summary",
        "disneyland_age",
        "disneyland_visit",
        "disneyland_button"
      ]
    },
    "disneyland_title": {
      "type": "Text",
      "props": {
        "text": "Tokyo Disneyland",
        "variant": "h3"
      },
      "children": []
    },
    "disneyland_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: Iconic theme park offering classic Disney rides, parades, and character experiences across seven themed lands."
      },
      "children": []
    },
    "disneyland_age": {
      "type": "Text",
      "props": {
        "text": "Age Suitability: Excellent for all ages, especially 8-12 year olds who love fantasy, adventure, and beloved Disney characters."
      },
      "children": []
    },
    "disneyland_visit": {
      "type": "Text",
      "props": {
        "text": "Estimated Visit: Full day (8-10 hours)."
      },
      "children": []
    },
    "disneyland_button": {
      "type": "Button",
      "props": {
        "label": "Book Tickets"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tokyodisneyresort.jp/en/ticket/"
          }
        }
      },
      "children": []
    },
    "ghibli_card": {
      "type": "Card",
      "props": {},
      "children": [
        "ghibli_content_stack"
      ]
    },
    "ghibli_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "ghibli_title_icon_stack",
        "ghibli_summary",
        "ghibli_age",
        "ghibli_visit",
        "ghibli_important",
        "ghibli_button"
      ]
    },
    "ghibli_title_icon_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "ghibli_icon",
        "ghibli_title"
      ]
    },
    "ghibli_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000270_01_4_wind.svg"
      },
      "children": []
    },
    "ghibli_title": {
      "type": "Text",
      "props": {
        "text": "Ghibli Museum (Mitaka)",
        "variant": "h3"
      },
      "children": []
    },
    "ghibli_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: A whimsical museum dedicated to the art and animation of Studio Ghibli, featuring original artwork, exhibits, and a short film exclusive to the museum."
      },
      "children": []
    },
    "ghibli_age": {
      "type": "Text",
      "props": {
        "text": "Age Suitability: Highly engaging for children who appreciate animation, imaginative storytelling, and the worlds of Totoro or Spirited Away."
      },
      "children": []
    },
    "ghibli_visit": {
      "type": "Text",
      "props": {
        "text": "Estimated Visit: 2-3 hours."
      },
      "children": []
    },
    "ghibli_important": {
      "type": "Text",
      "props": {
        "text": "Important: Tickets must be purchased in advance and are often sold out months ahead due to high demand."
      },
      "children": []
    },
    "ghibli_button": {
      "type": "Button",
      "props": {
        "label": "Check Booking"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ghibli-museum.jp/en/ticket/"
          }
        }
      },
      "children": []
    },
    "teamlab_card": {
      "type": "Card",
      "props": {},
      "children": [
        "teamlab_content_stack"
      ]
    },
    "teamlab_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "teamlab_title_icon_stack",
        "teamlab_summary",
        "teamlab_age",
        "teamlab_visit",
        "teamlab_button"
      ]
    },
    "teamlab_title_icon_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "teamlab_icon",
        "teamlab_title"
      ]
    },
    "teamlab_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000270_01_6_lightbulb.svg"
      },
      "children": []
    },
    "teamlab_title": {
      "type": "Text",
      "props": {
        "text": "teamLab Planets TOKYO",
        "variant": "h3"
      },
      "children": []
    },
    "teamlab_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: An immersive digital art museum where visitors step barefoot into captivating, interactive art installations that engage all senses."
      },
      "children": []
    },
    "teamlab_age": {
      "type": "Text",
      "props": {
        "text": "Age Suitability: Very popular with children and teenagers due to its highly interactive, sensory, and visually stunning nature."
      },
      "children": []
    },
    "teamlab_visit": {
      "type": "Text",
      "props": {
        "text": "Estimated Visit: 1.5-2.5 hours."
      },
      "children": []
    },
    "teamlab_button": {
      "type": "Button",
      "props": {
        "label": "Book Tickets"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://teamlabplanets.dmm.com/en"
          }
        }
      },
      "children": []
    },
    "ueno_zoo_card": {
      "type": "Card",
      "props": {},
      "children": [
        "ueno_zoo_content_stack"
      ]
    },
    "ueno_zoo_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "ueno_zoo_title_icon_stack",
        "ueno_zoo_summary",
        "ueno_zoo_age",
        "ueno_zoo_visit",
        "ueno_zoo_button"
      ]
    },
    "ueno_zoo_title_icon_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "ueno_zoo_icon",
        "ueno_zoo_title"
      ]
    },
    "ueno_zoo_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000241_01_4_tree.svg"
      },
      "children": []
    },
    "ueno_zoo_title": {
      "type": "Text",
      "props": {
        "text": "Ueno Zoo",
        "variant": "h3"
      },
      "children": []
    },
    "ueno_zoo_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: Japan's oldest zoo, renowned for its giant pandas and a diverse collection of animals from around the world, offering both outdoor and indoor exhibits."
      },
      "children": []
    },
    "ueno_zoo_age": {
      "type": "Text",
      "props": {
        "text": "Age Suitability: Excellent for animal-loving children, providing educational and engaging encounters with wildlife."
      },
      "children": []
    },
    "ueno_zoo_visit": {
      "type": "Text",
      "props": {
        "text": "Estimated Visit: 2-4 hours."
      },
      "children": []
    },
    "ueno_zoo_button": {
      "type": "Button",
      "props": {
        "label": "Visit Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tokyo-zoo.net/zoo/ueno/"
          }
        }
      },
      "children": []
    },
    "skytree_card": {
      "type": "Card",
      "props": {},
      "children": [
        "skytree_content_stack"
      ]
    },
    "skytree_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "skytree_title_icon_stack",
        "skytree_summary",
        "skytree_age",
        "skytree_visit",
        "skytree_button"
      ]
    },
    "skytree_title_icon_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "skytree_icon",
        "skytree_title"
      ]
    },
    "skytree_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000241_01_1_building.svg"
      },
      "children": []
    },
    "skytree_title": {
      "type": "Text",
      "props": {
        "text": "Tokyo Skytree",
        "variant": "h3"
      },
      "children": []
    },
    "skytree_summary": {
      "type": "Text",
      "props": {
        "text": "Summary: A towering broadcasting and observation tower offering panoramic views of Tokyo. Features two observation decks and a shopping complex."
      },
      "children": []
    },
    "skytree_age": {
      "type": "Text",
      "props": {
        "text": "Age Suitability: Great for children who enjoy heights and cityscapes; offers a unique perspective of Tokyo."
      },
      "children": []
    },
    "skytree_visit": {
      "type": "Text",
      "props": {
        "text": "Estimated Visit: 1.5-2.5 hours."
      },
      "children": []
    },
    "skytree_button": {
      "type": "Button",
      "props": {
        "label": "Book Tickets"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tokyo-skytree.jp/en/tickets/"
          }
        }
      },
      "children": []
    }
  }
}
